import sys

def add_todo(description):
    with open('todos.txt', 'a') as file:
        file.write(description + '\n')

def list_todos():
    try:
        with open('todos.txt', 'r') as file:
            lines = file.readlines()
            if not lines:
                print('No todos yet.')
            else:
                for index, line in enumerate(lines):
                    print(f'{index + 1}. {line.strip()}')
    except FileNotFoundError:
        print('No todos yet.')

def remove_todo(index):
    try:
        with open('todos.txt', 'r') as file:
            lines = file.readlines()
        if index <= 0 or index > len(lines):
            print('Invalid index.')
            return
        del lines[index - 1]
        with open('todos.txt', 'w') as file:
            file.writelines(lines)
        print(f'Todo at index {index} removed.')
    except FileNotFoundError:
        print('No todos yet.')

def main():
    if len(sys.argv) < 2:
        print('Usage: python todo.py [add|list|remove] <description|index>')
        sys.exit(1)

    command = sys.argv[1]

    if command == 'add':
        if len(sys.argv) != 3:
            print('Usage: python todo.py add <description>')
            sys.exit(1)
        description = sys.argv[2]
        add_todo(description)

    elif command == 'list':
        list_todos()

    elif command == 'remove':
        if len(sys.argv) != 3:
            print('Usage: python todo.py remove <index>')
            sys.exit(1)
        try:
            index = int(sys.argv[2])
            remove_todo(index)
        except ValueError:
            print('Invalid index.')

if __name__ == '__main__':
    main()
